cat > "$OUT/9.json" <<FWSHIFT_JSON
{"name": "fws-tcp-502", "destTcpPorts": [{"start": 502}], "type": "CUSTOM", "description": "FWShift"}
FWSHIFT_JSON
ID_9=$(create /networkServices 'fws-tcp-502' "$OUT/9.json" 9)
ID_10=$(need /locations 'eth3' 10)
ID_11=$(need /locations 'eth0' 11)
cat > "$OUT/12.json" <<FWSHIFT_JSON
{"name": "fws-tcp-8443", "destTcpPorts": [{"start": 8443}], "type": "CUSTOM", "description": "FWShift"}
