FWSHIFT_JSON
ID_15=$(create /firewallFilteringRules 'fws-Block bad hosts' "$OUT/15.json" 15)
cat > "$OUT/16.json" <<FWSHIFT_JSON
{"name": "fws-Guests stay in", "order": 3, "rank": 7, "action": "BLOCK_DROP", "state": "ENABLED", "locations": [{"id": ${ID_2}}], "srcIps": ["10.10.200.0/24"]}
