cat > "$OUT/17.json" <<FWSHIFT_JSON
{"name": "fws-LAN web", "order": 4, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_2}}], "nwServices": [{"id": ${ID_3}}]}
