cat > "$OUT/18.json" <<FWSHIFT_JSON
{"name": "fws-LAN DNS", "order": 5, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_2}}], "nwServices": [{"id": ${ID_4}}]}
