ID_18=$(create /firewallFilteringRules 'fws-LAN DNS' "$OUT/18.json" 18)
cat > "$OUT/19.json" <<FWSHIFT_JSON
{"name": "fws-Rate limited mail", "order": 6, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "locations": [{"id": ${ID_2}}], "nwServices": [{"id": ${ID_5}}]}
