cat > "$OUT/21.json" <<FWSHIFT_JSON
{"name": "fws-Admins", "order": 8, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_2}}], "srcIpGroups": [{"id": ${ID_7}}], "destAddresses": ["10.20.0.0/24"], "nwServices": [{"id": ${ID_8}}]}
