{"name": "fws-SCADA to PLCs", "order": 10, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_2}}], "srcIps": ["10.10.7.15"], "destAddresses": ["10.30.1.0/24"], "nwServices": [{"id": ${ID_9}}]}
